l theme ui',\n    视觉: 'vision image ui', 看图: 'image vision picture', 图片: 'image picture',\n    通知: 'notify notification', 提醒: 'notify reminder',\n    任务板: 'board kanban task', 看板: 'board kanban',\n    导出: 'export', 导入: 'import', 备份: 'backup export',\n    搜索: 'search', 搜索增强: 'search', 翻译: 'translate', 写作: 'writing write',\n    润色: 'polish writing', 预设: 'preset', 场景: 'preset scenario',\n    游戏: 'game', 调试: 'debug', 测试: 'test', 文档: 'doc documentation',\n    图表: 'chart graph', 日报: 'daily report', 周报: 'weekly report', 日志: 'log',\n    工作流: 'workflow', 实验: 'lab experiment', 安全: 'security',\n    皮肤中心: 'theme', 商店: 'store manager', 更新: 'update upgrade',\n    插件: 'plugin', 小红书: 'xiaohongshu', 日历: 'calendar', 护眼: 'dark theme',\n  }\n  // v0.6 F-J: 反馈入口 —— 第一方 → dsh-suite 集中收编；第三方 → 插件作者仓库\n  const FEEDBACK_CENTER = 'https://github.com/whyihaveyou/dsh-suite/issues/new'\n  // v0.7 F-H: 场景组合（与 site/build.mjs SCENARIOS 同步）—— 本期仅 UI + 逐包串行\n  // 调既有 /plugin-manager/install；应用预设留 设置 → Agent presets（host apply-preset 另行评审）\n  const SCENES = [\n    { id: 'xhs', emoji: '📕',\n      title: { zh: '小红书创作套装', en: 'Xiaohongshu Creator Kit' },\n      blurb: { zh: '预设 + 主题一键到位，苹果皮配好即开写。', en: 'Preset + theme in one go, ready to write.' },\n      items: [\n        { pkg: '@dsh-suite/preset-center', note: { zh: '场景预设（小红书笔记等）', en: 'scenario presets (xiaohongshu notes etc.)' } },\n        { pkg: '@dsh-suite/themes', note: { zh: '苹果皮主题包', en: 'theme pack' } },\n      ], presetGuide: true },\n    { id: 'dev', emoji: '🛠️',\n      title: { zh: '开发者效率套件', en: 'Developer Productivity' },\n      blurb: { zh: '管插件、导会话，两块硬骨头一次啃完。', en: 'Manage plugins & export sessions in one click.' },\n      items: [\n        { pkg: '@dsh-suite/plugin-manager', note: { zh: '插件管理中枢', en: 'plugin hub (this one!)' } },\n        { pkg: '@dsh-suite/plugin-session-export', note: { zh: '会话导出 Markdown/HTML', en: 'session export to Markdown/HTML' } },\n      ] },\n    { id: 'gamer', emoji: '🎮',\n      title: { zh: '玩家美化套装', en: 'Gamer Makeover' },\n      blurb: { zh: '换皮是刚需，一套主题全家桶。', en: 'A full theme wardrobe for your DSH.' },\n      items: [\n        { pkg: '@dsh-suite/themes', note: { zh: '主题市场（多套皮肤）', en: 'theme gallery' } },\n      ] },\n    { id: 'notify', emoji: '🔔',\n      title: { zh: '提醒不漏接', en: 'Never Miss a Beat' },\n      blurb: { zh: '跑长任务不再盯屏，出声提醒。', en: 'Audible nudges when long tasks finish.' },\n      items: [\n        { pkg: '@dsh-suite/plugin-notify', note: { zh: '任务完成系统声音提醒', en: 'system sound on task finish' } },\n      ] },\n    { id: 'writing', emoji: '✍️',\n      title: { zh: '写作润色工坊', en: 'Writing & Polish Studio' },\n      blurb: { zh: '主题护眼 + 写完随手导出。', en: 'Eye-candy theme + one-click export.' },\n      items: [\n        { pkg: '@dsh-suite/themes', note: { zh: '写作向主题（护眼配色）', en: 'writing-friendly themes' } },\n        { pkg: '@dsh-suite/plugin-session-export', note: { zh: '草稿一键导出 Markdown', en: 'export drafts to Markdown' } },\n      ] },\n    { id: 'daily', emoji: '📊',\n      title: { zh: '日报速记套装', en: 'Daily Report Starter' },\n      blurb: { zh: '会话存证，贴进日报周报不慌。', en: 'Archive sessions for painless weekly reports.' },\n      items: [\n        { pkg: '@dsh-suite/plugin-session-export', note: { zh: '会话存档，周报素材', en: 'session archive for reports' } },\n      ] },\n  ]\n\n  function feedbackUrl(p) {\n    const own = (p && p.repo) || ''\n    const firstParty = own.startsWith('whyihaveyou/') || (own.includes('dsh-suite') && !own.includes('/plugins/'))\n    if (firstParty) {\n      const nm = (p && (p.name || '')) || ''\n      return FEEDBACK_CENTER + '?title=' + encodeURIComponent('用户反馈：' + nm)\n        + '&body=' + encodeURIComponent('请描述你遇到的问题或建议：\\n- 插件/组件：' + nm + '\\n- 环境（DSH 版本 / OS）：\\n- 现象：\\n- 期望：\\n- 日志或截图（如果有）：\\n')\n    }\n    if (own) return 'https://github.com/' + own + '/issues/new'\n    return FEEDBACK_CENTER + '?title=' + encodeURIComponent('用户反馈：' + ((p && p.name) || '（未署名插件）'))\n  }\n\n      // v0.8.1 P0: WKWebView/Electron 壳兼容 —— 壳（HarnessShell@aion2dsh）未实现\n      // WKUIDelegate.createWebViewWith / decidePolicyFor，target=_blank 点击被静默丢弃。\n      // 外链打开：行为检测而非 UA/对象嗅探——裸 WKWebView（WhalePod 壳，无 WKUIDelegate）\n      // 实测 window.open() 恒返回 null（no-gesture 与 click-gesture 均 null，见 0.8.1 排查记录），\n      // 真实浏览器点击手势下返回 Window 对象；返回 falsy 即判定被吞，降级「复制 + toast」。\n      // （曾经的 window.webkit 嗅探无效：未注册 message handler 的 WKWebView 里 window.webkit 为 undefined。）\n      function legacyCopy(txt) {\n        try {\n          const ta = document.createElement('textarea')\n          ta.value = txt; ta.style.cssText = 'position:fixed;opacity:0;'\n          document.body.appendChild(ta); ta.select()\n          document.execCommand('copy'); ta.remove()\n        } catch { /* no-op */ }\n      }\n      function copyExternalText(txt) {\n        try {\n          if (navigator.clipboard && navigator.clipboard.writeText) {\n            navigator.clipboard.writeText(txt).catch(() => legacyCopy(txt))\n          } else legacyCopy(txt)\n        } catch { legacyCopy(txt) }\n      }\n      function showExtToast(url) {\n        try {\n          const old = document.querySelector('[data-open-ext-toast]')\n          if (old) old.remove()\n          const el = document.createElement('div')\n          el.setAttribute('data-open-ext-toast', '1')\n          el.style.cssText = 'position:fixed;left:50%;bottom:22px;transform:translateX(-50%);z-index:99999;background:var(--dsw-alias-bg-layer-1);border:1px solid var(--dsw-alias-border-l1);border-radius:10px;padding:10px 14px;max-width:min(520px,80vw);box-shadow:0 8px 24px rgba(0,0,0,0.5);display:flex;gap:10px;align-items:flex-start;'\n          const sp = document.createElement('span')\n          sp.style.cssText = 'font-size:12px;color:var(--dsw-alias-label-primary);line-height:1.5;word-break:break-all;'\n          // 模块作用域拿不到 ctx.locale；shell/浏览器语言直接用 navigator.language 判定\n          const isZh = ((typeof navigator !== 'undefined' && navigator.language) || '').toLowerCase().indexOf('zh') === 0\n          sp.textContent = (isZh ? '🔗 链接已复制——到浏览器粘贴打开：' : '🔗 Link copied — paste it in your browser: ') + url\n          const x = document.createElement('button')\n          x.textContent = '×'\n          x.style.cssText = 'background:none;border:none;color:var(--dsw-alias-label-secondary);font-size:14px;cursor:pointer;flex-shrink:0;padding:0;'\n          x.onclick = () => el.remove()\n          el.appendChild(sp); el.appendChild(x)\n          // 挂 <html> 而非 <body>：dsh web 宿主挂在 body 上，重渲染会把 body 下外来节点清掉\n          // (实测 WKWebView 中 toast append 后 ~1s 内被宿主重渲染抹除)。\n          ;(document.documentElement || document.body).appendChild(el)\n          setTimeout(() => { try { el.remove() } catch (_) {} }, 6000)\n        } catch { /* no-op */ }\n      }\n      function openExternal(url) {\n        if (!url) return\n        let w = null\n        try { w = window.open(url, '_blank', 'noopener') } catch { w = null }\n        if (w) return // 真浏览器（点击手势）返回 Window —— 已接管新标签\n        try { copyExternalText(url) } catch { /* WKWebView 剪贴板可能抛错，提示必须照出 */ }\n        showExtToast(url) // 壳内被吞（window.open 返回 null）→ 复制 + 提示\n      }\n  function searchAliases(qRaw) {\n    const extras = []\n    for (const k of Object.keys(ZH_ALIAS)) if (qRaw.includes(k)) extras.push(ZH_ALIAS[k])\n    return extras.join(' ')\n  }\n  const CATEGORIES = ['all', 'tools', 'ui', 'session', 'llm', 'orchestration', 'utility', 'workflow', 'integration', 'skill', 'dev-tool', 'other']\n\n    // ---------- small UI helpers (theme-aware: colors use dsw CSS vars so the\n    // store follows the active light/dark theme instead of forcing dark) ----------\n    const C = {\n      card: { background: 'var(--dsw-alias-bg-layer-1)', border: '1px solid var(--dsw-alias-border-l1)', borderRadius: '8px', padding: '14px', display: 'flex', flexDirection: 'column', gap: '8px', minHeight: '150px' },\n      featWrap: { display: 'flex', gap: '12px', overflowX: 'auto', padding: '2px 2px 8px', marginBottom: '4px' },\n      featCard: { flex: '0 0 264px', background: 'var(--dsw-alias-bg-layer-1)', border: '1px solid var(--dsw-alias-brand-primary)', borderRadius: '10px', overflow: 'hidden', cursor: 'pointer', display: 'flex', flexDirection: 'column' },\n      featImgBox: { width: '100%', height: '118px', background: 'var(--dsw-alias-bg-layer-2)' },\n      featBody: { padding: '10px 12px', display: 'flex', flexDirection: 'column', gap: '6px' },\n      featDesc: { fontSize: '12px', color: 'var(--dsw-alias-label-secondary)', lineHeight: '1.4', display: '-webkit-box', WebkitLineClamp: '2', WebkitBoxOrient: 'vertical', overflow: 'hidden' },\n      name: { fontSize: '15px', fontWeight: '600', color: 'var(--dsw-alias-label-primary)', display: 'flex', alignItems: 'center', gap: '6px', flexWrap: 'wrap' },\n      desc: { fontSize: '12px', color: 'var(--dsw-alias-label-secondary)', lineHeight: '1.4' },\n      descZh: { fontSize: '12px', color: 'var(--dsw-alias-label-secondary)', lineHeight: '1.4' },\n      meta: { fontSize: '11px', color: 'var(--dsw-alias-label-secondary)', display: 'flex', gap: '8px', alignItems: 'center', flexWrap: 'wrap' },\n      // 契约 primary-action-tokens/v1：填充主按钮用四件套（fill/foreground/hover/dimmed），禁止硬编码 accent\n      btn: { background: 'var(--dsw-alias-button-primary-fill)', color: 'var(--dsw-alias-label-primary-foreground)', border: 'none', borderRadius: '6px', padding: '6px 12px', fontSize: '12px', cursor: 'pointer', fontWeight: '600' },\n      btnGhost: { background: 'transparent', color: 'var(--dsw-alias-label-primary)', border: '1px solid var(--dsw-alias-border-l1)', borderRadius: '6px', padding: '6px 10px', fontSize: '12px', cursor: 'pointer' },\n      btnDisabled: { background: 'var(--dsw-alias-button-primary-dimmed)', color: 'var(--dsw-alias-label-primary-foreground)', border: 'none', borderRadius: '6px', padding: '6px 12px', fontSize: '12px', cursor: 'not-allowed' },\n      badge: (color) => ({ display: 'inline-flex', alignItems: 'center', gap: '4px', fontSize: '11px', color, border: '